<div class="weekbar"><a class="button secondary small" href="{{ route($page,['week'=>$week->subWeek()->toDateString()]) }}" aria-label="Previous week">←</a><strong>{{ $week->format('j M') }} – {{ $week->addDays(6)->format('j M Y') }}</strong><a class="button secondary small" href="{{ route($page,['week'=>$week->addWeek()->toDateString()]) }}" aria-label="Next week">→</a><form method="get" action="{{ route($page) }}"><label>Week containing<input type="date" name="week" value="{{ $week->toDateString() }}" required></label><button class="small secondary">Go</button></form></div>
